.mm-dashboard .mmd-main{ overflow-y:auto; }
/* 大屏时整屏锁高：顶部 header 固定，主内容区在视口内自成滚动容器。
   屏幕高度充足时各面板自然铺满、无滚动；高度不足（如 1920x953 / 1366x768）时
   主内容区内部纵向滚动，绝不溢出/裁切视口。 */
@media (min-width:1024px){
  .mm-dashboard.mmd-screen{ height:100vh; min-height:0; overflow:hidden; }
  .mm-dashboard .mmd-main{ flex:1 1 0%; min-height:0; overflow-y:auto; overflow-x:hidden; }
  .mm-dashboard .mmd-row1{ flex:1.45 1 0%; min-height:0 !important; }
  .mm-dashboard .mmd-row2{ flex:0.8 1 0%; min-height:0 !important; }
}

